-- Runtime error messages with variable names in all contexts.
local function e(f, ...)
  local ok, msg = pcall(f, ...)
  print(ok, msg)
end

-- globals, locals, upvalues, fields, methods, constants
e(function() undefinedglobal() end)
e(function() local x; x() end)
local up
e(function() up() end)
e(function() local t = {} t.field() end)
e(function() local t = {} t:method() end)
e(function() local t = {} t.a.b = 1 end)
e(function() local t = {} return t.a.b end)
e(function() return undefinedglobal.x end)
e(function() undefinedglobal.x = 1 end)
e(function() local s = "x"; return s.y.z end)
e(function() return ("x")() end)
e(function() return (1)() end)
e(function() local t = {} return t[1]() end)
e(function() local t = {} local k = "key" return t[k]() end)
e(function() local t = {} return t[true]() end)
e(function() return up.x end)
e(function() up.x = 1 end)
e(function() local a = {} ; a[nil] = 1 end)
e(function() local a = {} ; a[0/0] = 1 end)
e(function() rawset({}, nil, 1) end)

-- arithmetic
e(function() local a; return a + 1 end)
e(function() return up + 1 end)
e(function() return 1 + {} end)
e(function() local t = {} return t.x * 2 end)
e(function() return -{} end)
e(function() local s = "abc"; return s + 1 end)
e(function() return "10" + "x" end)
e(function() return 2 ^ nil end)
e(function() local t = {} return t % 1 end)
e(function() return undefinedglobal / 2 end)
e(function() local a, b = 1 return a - b end)
-- concatenation
e(function() local a; return "x" .. a end)
e(function() return {} .. "x" end)
e(function() local t = {} return "a" .. t.f .. "b" end)
e(function() return 1 .. nil end)
e(function() return true .. "x" end)
-- comparison
e(function() return 1 < "2" end)
e(function() return {} < {} end)
e(function() return nil < 1 end)
e(function() return "a" <= 1 end)
e(function() return {} > 1 end)
e(function() return true >= false end)
e(function() local a = setmetatable({}, {}) return a < a end)
-- length
e(function() local n = 5; return #n end)
e(function() return #undefinedglobal end)
e(function() local t = {} return #t.x end)
-- for loops
e(function() for i = 1, "x" do end end)
e(function() for i = nil, 10 do end end)
e(function() for i = 1, 10, {} do end end)
e(function() for k, v in 42 do end end)
e(function() for k, v in nil do end end)
-- calls with arguments
e(function() string.rep() end)
e(function() ("x"):rep() end)
e(function() ("x"):bad() end)
e(function() local s = "x"; s:rep("y") end)
e(function() setmetatable(1, {}) end)
e(function() table.insert(nil, 1) end)
e(function() table.insert({}, 1, 2, 3) end)
e(function() table.concat({{}}) end)
e(function() table.concat({1, 2, {}}, ",") end)
e(function() ipairs() end)
e(function() select(0) end)
e(function() select(-5, 1) end)
e(function() tostring() end)
e(function() tonumber("10", 99) end)
e(function() tonumber() end)
e(function() string.char(256) end)
e(function() string.char(-1) end)
e(function() string.format("%d", "x") end)
e(function() string.format("%y", 1) end)
e(function() string.format("%", 1) end)
e(function() string.format("%10.123f", 1) end)
e(function() string.format("%s") end)
e(function() string.rep("x", -1, {}) end)
e(function() math.floor("a") end)
e(function() math.max() end)
e(function() coroutine.resume(1) end)
e(function() coroutine.wrap(1) end)
e(function() unpack({}, 1, 1e8) end)
e(function() setfenv(100, {}) end)
e(function() getfenv(-1) end)
e(function() error() end)
e(function() error(nil) end)
e(function() error({}) end)
e(function() error("msg", 0) end)
e(function() error("msg", 1) end)
e(function() error("msg", 2) end)
e(function() error("msg", 3) end)
e(function() error(42) end)
e(function() assert(false) end)
e(function() assert(nil, "custom") end)
e(function() assert(false, {}) end)
e(function() assert() end)
e(function() local t = setmetatable({}, {__index = function(t, k) error("idx " .. k) end}) return t.foo end)
e(function() local t = setmetatable({}, {__newindex = "notatable"}) t.x = 1 end)
e(function() local t = setmetatable({}, {__call = 1}) t() end)
e(function() local t = setmetatable({}, {__metatable = "locked"}) setmetatable(t, {}) end)
e(function() string.dump(print) end)
e(function() load(1) end)
e(function() loadstring() end)
e(function() next({}, "nokey") end)
e(function() local t = {1} for k in pairs(t) do t.newkey = 1 end end)
e(function() xpcall() end)
e(function() return xpcall(error, nil, "x") end)
e(function() newproxy(1) end)
e(function() collectgarbage("bogus") end)
e(function() os.date(1, "x") end)
e(function() io.open("x", "rz") end)
e(function() io.lines("/nonexistent/file") end)
e(function() string.sub() end)
e(function() ("x"):sub({}) end)
e(function() bit.band("x") end)
e(function() bit.tohex({}) end)
e(function() table.sort({3, 1, 2}, function(a, b) return a.x end) end)
e(function() table.sort({1, "x", 2}) end)
e(function() math.random(2, 1) end)
e(function() math.random(1, 2, 3) end)
e(function() debug.getlocal(100, 1) end)
e(function() debug.setlocal(1, 100, 1) end)
e(function() debug.getinfo("x") end)
e(function() debug.getinfo(1, ">") end)
e(function() debug.sethook(1) end)
e(function() string.gsub("x", "(", "") end)
e(function() string.gsub("x", "%", "") end)
e(function() string.find("x", "[a") end)
e(function() string.gsub("abc", "(a)", "%2") end)
e(function() string.gsub("abc", "a", {}, "x") end)
e(function() string.gsub("abc", "a", true) end)
e(function() string.rep("x", 1e10) end)
-- error positions and levels inside nested functions
local function lvl1() error("deep", 2) end
local function lvl2() lvl1() end
e(lvl2)
e(function() local a = {} ; a.b.c.d = 1 end)
-- method call on nil field of upvalue
local obj = {}
e(function() obj:nomethod() end)
e(function() obj.sub:nomethod() end)
-- operations on varargs
e(function(...) local a = ... ; return a.x end)
e(function(...) return (...).x end, nil)
-- string methods with wrong self
e(function() return ("x").upper(nil) end)
-- integer conversions
e(function() return ("x"):rep(1.5) end)
e(function() return string.char(65.5) end)
-- error objects through pcall boundaries
print(select('#', pcall(error)))
print(pcall(error, setmetatable({}, {__tostring = function() return "TS" end})))
print(xpcall(function() error("E") end, function(m) return "handled: " .. m end))
print(xpcall(function() error("E") end, function(m) error("in handler") end))
print(xpcall(function() local x = nil; x() end, debug.traceback))
